"""Download external assets that are not generated by this repo.

    python -m scripts.download_assets --task3-repo <hf-dataset-id-or-url-from-LMS> [--coco] [--vqa]

Task 3 rollouts (ATML-PA3-Data) are distributed with the assignment; pass the Hugging Face dataset id given there.
COCO 2014 and VQAv2 complementary pairs are downloaded from their official hosts.
"""
from __future__ import annotations

import argparse
import subprocess
import zipfile

from common.utils import repo_path

COCO = {
    "train2014": "http://images.cocodataset.org/zips/train2014.zip",
    "val2014": "http://images.cocodataset.org/zips/val2014.zip",
    "annotations": "http://images.cocodataset.org/annotations/annotations_trainval2014.zip",
}
VQA = {
    "v2_Questions_Train_mscoco.zip": "https://cvmlp.s3.amazonaws.com/vqa/mscoco/vqa/v2_Questions_Train_mscoco.zip",
    "v2_Questions_Val_mscoco.zip": "https://cvmlp.s3.amazonaws.com/vqa/mscoco/vqa/v2_Questions_Val_mscoco.zip",
    "v2_Annotations_Train_mscoco.zip": "https://cvmlp.s3.amazonaws.com/vqa/mscoco/vqa/v2_Annotations_Train_mscoco.zip",
    "v2_Annotations_Val_mscoco.zip": "https://cvmlp.s3.amazonaws.com/vqa/mscoco/vqa/v2_Annotations_Val_mscoco.zip",
    "v2_Complementary_Pairs_Train_mscoco.zip": "https://cvmlp.s3.amazonaws.com/vqa/mscoco/vqa/v2_Complementary_Pairs_Train_mscoco.zip",
    "v2_Complementary_Pairs_Val_mscoco.zip": "https://cvmlp.s3.amazonaws.com/vqa/mscoco/vqa/v2_Complementary_Pairs_Val_mscoco.zip",
}


def fetch(url: str, dest_dir, extract_to=None):
    dest_dir.mkdir(parents=True, exist_ok=True)
    f = dest_dir / url.rsplit("/", 1)[-1]
    if not f.exists():
        subprocess.run(["curl", "-L", "-o", str(f), url], check=True)
    with zipfile.ZipFile(f) as z:
        z.extractall(extract_to or dest_dir)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--task3-repo", default=None)
    ap.add_argument("--coco", action="store_true")
    ap.add_argument("--vqa", action="store_true")
    args = ap.parse_args()
    if args.task3_repo:
        from huggingface_hub import snapshot_download
        snapshot_download(repo_id=args.task3_repo, repo_type="dataset", local_dir=repo_path("data/ATML-PA3-Data"))
    if args.coco:
        for name, url in COCO.items():
            fetch(url, repo_path("data/coco/_zips"), repo_path("data/coco"))
    if args.vqa:
        for name, url in VQA.items():
            fetch(url, repo_path("data/vqav2/_zips"), repo_path("data/vqav2"))


if __name__ == "__main__":
    main()
